&reftitle.description;
public Yaf_Application::__construct stringarrayconfig stringnullenvironnull
Instancia uma Yaf_Application. O construtor também inicializa o singleton da aplicação, o Yaf_Loader e o Yaf_Dispatcher, portanto deve ser chamado antes de qualquer um deles ser usado.

  &reftitle.examples;

   Exemplo de Yaf_Application::__construct


<?php
defined('APPLICATION_PATH')                  // APPLICATION_PATH será usada no arquivo INI de configuração
    || define('APPLICATION_PATH', __DIR__);

$application = new Yaf_Application(APPLICATION_PATH.'/conf/application.ini');
$application->bootstrap()->run();
?>




   Exemplo de Yaf_Application::__construct


<?php
$config = array(
    "application" => array(
        "directory" => realpath(dirname(__FILE__)) . "/application",
    ),
);

/** Yaf_Application */
$application = new Yaf_Application($config);
$application->bootstrap()->run();
?>
